from copy import deepcopy
import json

import pytest

from finbot_earnings.processing.contracts import FilingReady
from finbot_earnings.processing.errors import ContractError
from tests.processing_helpers import fixture, rehash


def test_independent_producer_golden_vector():
    # Copied contract vector, deliberately not generated by the consumer or imported from filings.
    accession = "0000320193-26-000001"
    payload = dict(event_type="filing.ready", schema_version="1.0", filing_id=accession,
        snapshot_id="29329bd911d01c5b947a0fed704928e364944b0d8f3590e8a5f87fc88779ba1e",
        cik="0000320193", ticker="AAPL", company_name="Apple", form_type="8-K",
        filed_at="2026-10-08T19:59:50.000000Z", ready_at="2026-10-08T20:00:00.000000Z",
        primary_artifact_id=accession + "/Primary.htm", artifacts=[
            dict(artifact_id=accession + "/" + name, filename=name,
                 s3_uri="s3://artifacts/AAPL/" + name, size_bytes=3)
            for name in ("release.htm", "Primary.htm")])
    parsed = FilingReady.parse(payload)
    assert [item.filename for item in parsed.artifacts] == ["Primary.htm", "release.htm"]
    payload["ready_at"] = "2026-10-09T20:00:00.000000Z"
    assert FilingReady.parse(payload).snapshot_id == parsed.snapshot_id


def test_raw_and_sns_notifications_and_topic_check():
    payload, _, _ = fixture()
    wrapped = dict(Type="Notification", TopicArn="expected", Message=json.dumps(payload))
    assert FilingReady.parse(json.dumps(wrapped), expected_topic_arn="expected").to_dict() == FilingReady.parse(payload).to_dict()
    with pytest.raises(ContractError):
        FilingReady.parse(wrapped, expected_topic_arn="other")
    assert FilingReady.parse(json.dumps(payload).encode()).filing_id == payload["filing_id"]


@pytest.mark.parametrize("change", [
    lambda p: p.update(event_type="artifact.ready"),
    lambda p: p.update(schema_version="2.0"),
    lambda p: p.update(cik="320193"),
    lambda p: p.update(snapshot_id="0" * 64),
    lambda p: p.update(ready_at="2026-10-14T00:00:01Z"),
    lambda p: p.update(filed_at="2026-02-30T00:00:00.000000Z"),
    lambda p: p.update(extra=True),
    lambda p: p.update(artifacts=[]),
    lambda p: p["artifacts"].append(deepcopy(p["artifacts"][0])),
    lambda p: p.update(primary_artifact_id="missing"),
    lambda p: p["artifacts"][0].update(size_bytes=True),
    lambda p: p["artifacts"][0].update(content_type=None),
    lambda p: p["artifacts"][0].update(filename="../escape.htm"),
    lambda p: p["artifacts"][0].update(s3_uri="s3://artifacts/key?version=x"),
    lambda p: p["artifacts"][0].update(s3_uri="s3://artifacts/%ff"),
])
def test_invalid_contracts(change):
    payload, _, _ = fixture()
    change(payload)
    with pytest.raises(ContractError):
        FilingReady.parse(payload)


def test_json_duplicate_keys_and_nonfinite_rejected():
    for message in ('{"event_type":"filing.ready","event_type":"other"}', '{"value":NaN}'):
        with pytest.raises(ContractError):
            FilingReady.parse(message)


def test_case_unicode_optional_metadata_and_encoded_key_affect_hash():
    payload, _, _ = fixture()
    payload["company_name"] = "Éxample 公司"
    payload["artifacts"][0].update(s3_uri="s3://artifacts/a%20b%23c.htm", document_type="8-K")
    rehash(payload)
    assert FilingReady.parse(payload).company_name == "Éxample 公司"
    payload["artifacts"][0]["document_type"] = "EX-99.1"
    with pytest.raises(ContractError):
        FilingReady.parse(payload)
